exercises.solutionCode:
#include <stddef.h>
#include <stdint.h>

#define DEV_MAJOR_BITS 12u
#define DEV_MINOR_BITS 20u

#define DEV_MAJOR_MAX ((1u << DEV_MAJOR_BITS) - 1u)  /* 4095    */
#define DEV_MINOR_MAX ((1u << DEV_MINOR_BITS) - 1u)  /* 1048575 */

int dev_make(unsigned int major, unsigned int minor, uint32_t *out_dev)
{
    if (out_dev == NULL) {
        return -1;
    }
    if (major > DEV_MAJOR_MAX || minor > DEV_MINOR_MAX) {
        return -1;
    }

    *out_dev = ((uint32_t)major << DEV_MINOR_BITS) | (uint32_t)minor;
    return 0;
}

int dev_split(uint32_t dev, unsigned int *out_major, unsigned int *out_minor)
{
    if (out_major == NULL || out_minor == NULL) {
        return -1;
    }

    *out_major = (unsigned int)((dev >> DEV_MINOR_BITS) & DEV_MAJOR_MAX);
    *out_minor = (unsigned int)(dev & DEV_MINOR_MAX);
    return 0;
}
